-- Sendro Instagram / SaaS database Step 4: channel-scoped conversations.
-- MANUAL EXECUTION ONLY. Staging and production share one PostgreSQL DB.
-- Prerequisite: empty public.sendro_channel_accounts and 13 memberships
-- on tenant sunset-oia, plus a current verified backup.
-- This migration adds ONE NEW EMPTY TABLE; it does not touch WhatsApp.

BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';

CREATE TABLE public.sendro_channel_conversations (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tenant_id BIGINT NOT NULL,
    channel_account_id BIGINT NOT NULL,
    external_customer_id VARCHAR(128) NOT NULL,
    contact_name VARCHAR(160),
    status VARCHAR(16) NOT NULL DEFAULT 'open',
    assigned_to_user_id INTEGER,
    unread_count INTEGER NOT NULL DEFAULT 0,
    last_message_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_sendro_channel_conversations_account_tenant
        FOREIGN KEY (channel_account_id, tenant_id)
        REFERENCES public.sendro_channel_accounts(id, tenant_id)
        ON DELETE RESTRICT,
    CONSTRAINT fk_sendro_channel_conversations_assigned_member
        FOREIGN KEY (tenant_id, assigned_to_user_id)
        REFERENCES public.sendro_tenant_users(tenant_id, user_id)
        ON DELETE RESTRICT,
    CONSTRAINT uq_sendro_channel_conversations_account_customer
        UNIQUE (channel_account_id, external_customer_id),
    CONSTRAINT uq_sendro_channel_conversations_id_tenant_account
        UNIQUE (id, tenant_id, channel_account_id),
    CONSTRAINT ck_sendro_channel_conversations_customer
        CHECK (LENGTH(BTRIM(external_customer_id)) > 0),
    CONSTRAINT ck_sendro_channel_conversations_status
        CHECK (status IN ('open', 'closed', 'archived')),
    CONSTRAINT ck_sendro_channel_conversations_unread
        CHECK (unread_count >= 0)
);

CREATE INDEX idx_sendro_channel_conversations_tenant_status_updated
    ON public.sendro_channel_conversations
    (tenant_id, status, updated_at DESC, id DESC);

COMMIT;

-- Postflight: expect 11 columns, zero rows, 2 foreign keys.
-- No accounts/conversations are inserted by this script.
